using namespace mka::video;
void check(bool b,const char* s){if(!b)throw std::runtime_error(s);}
void quote(const std::string& s){std::putchar('"');for(unsigned char c:s){if(c=='"'||c=='\\'){std::putchar('\\');std::putchar(c);}else if(c<32||c>=127)std::printf("\\u%04x",unsigned(c));else std::putchar(c);}std::putchar('"');}
void hex(std::span<const std::uint8_t> b){for(auto c:b)std::printf("%02x",unsigned(c));}
std::string digest(std::span<const std::uint8_t> b){NativeTestSha256 h;h.add(b.data(),b.size());return h.finish();}
struct Observation{std::string pcm;MovieAdxStreamSnapshot final;std::uint64_t count=0,reported_raw=0;};
Observation decode(std::span<const std::uint8_t> bytes,bool chunked){
    MovieAdxHeaderFailure hf;auto source_header=parse_movie_adx_header(bytes,hf);check(bool(source_header),"trace expected header rate");MovieAdxStreamFailure f;auto stream=NativeMovieAdxStream::create({},std::make_unique<NativeMovieAdxProfileResolver>(),f);check(bool(stream),"concrete native stream");NativeTestSha256 hash;std::uint64_t frames=0,reported_raw=0;std::optional<MovieAdxStreamFrame> held;
    const auto consume=[&](MovieAdxStreamResult result){check(result.status!=MovieAdxStreamStatus::error&&f.kind==MovieAdxStreamError::none,"actual source native stream feed");if(result.frame){auto& frame=*result.frame;check(frame.first_source_frame==frames&&frame.planes.size()==2&&!frame.planes[0].empty()&&frame.planes[0].size()==frame.planes[1].size(),"contiguous equal native source plane output");check(frame.sample_rate==source_header->sample_rate&&frame.raw_decoded_frames%32==0&&frame.raw_decoded_frames>=frame.planes[0].size(),"each emitted frame rate/raw group metadata");check(frame.raw_decoded_frames<=UINT64_MAX-reported_raw,"reported raw native sum");reported_raw+=frame.raw_decoded_frames;check(frame.planes[0].size()<=UINT64_MAX-frames,"native frame counter");for(std::size_t i=0;i<frame.planes[0].size();++i)for(const auto& plane:frame.planes){const auto word=static_cast<std::uint16_t>(plane[i]);std::array<std::uint8_t,2> le{std::uint8_t(word&255),std::uint8_t(word>>8)};hash.add(le.data(),le.size());}frames+=frame.planes[0].size();held=std::move(frame);}};
    if(!chunked)consume(stream->feed(bytes,f));else{constexpr std::array<std::size_t,6> sizes{1,7,35,36,277,4096};std::size_t offset=0,ordinal=0;while(offset<bytes.size()){auto n=std::min(sizes[ordinal++%sizes.size()],bytes.size()-offset);consume(stream->feed(bytes.subspan(offset,n),f));offset+=n;}}
    check(stream->finish(f).status==MovieAdxStreamStatus::ended&&f.kind==MovieAdxStreamError::none,"explicit encoded finish");auto state=stream->snapshot(f);check(state&&state->header&&state->encoded_ended&&!state->failed&&state->carry.empty()&&held,"complete owned stream snapshot");check(reported_raw==state->raw_decoded_frames,"sum of frame raw metadata matches committed snapshot");const auto retained_sample=held->planes[0].back();stream.reset();check(held->planes[0].back()==retained_sample&&state->header->raw_header.size()>=38,"PCM/header survives stream release");return {hash.finish(),std::move(*state),frames,reported_raw};
}
int main(int argc,char** argv){try{
    check(argc==3,"usage: test_native_movie_adx_audio_assets asset-root 38entrycatalog.tsv");std::ifstream manifest(std::filesystem::u8path(argv[2]),std::ios::binary);check(bool(manifest),"explicit catalog open");std::vector<MovieAssetCatalogEntry> catalog;std::set<std::string> keys,paths;std::string line;
    while(std::getline(manifest,line)){if(!line.empty()&&line.back()=='\r')line.pop_back();const auto tab=line.find('\t');check(tab!=line.npos&&tab>0&&tab+1<line.size()&&line.find('\t',tab+1)==line.npos,"exact key/tab/relative-file catalog row");auto key=line.substr(0,tab),relative=line.substr(tab+1);check(key.find('\0')==key.npos&&relative.find('\0')==relative.npos&&keys.insert(key).second&&paths.insert(relative).second,"unique catalog key/file");catalog.push_back({std::move(key),std::move(relative)});}
    check(manifest.eof()&&!manifest.bad()&&catalog.size()==38,"exact complete38 catalog");MovieAssetFailure af;auto store=NativeMovieAssetStore::create(std::filesystem::u8path(argv[1]),catalog,af);check(bool(store),"native actual-handle asset store");std::size_t audio_count=0,video_only=0;
    for(const auto& entry:catalog){auto asset=store->open(entry.logical_utf8,af);check(bool(asset),"same-bound source asset open");MoviePesFailure f;auto index=NativeMoviePesIndex::build(std::move(*asset),f);check(bool(index),"source audio/video index");auto videos=index->streams(),audios=index->audio_streams();check(videos.size()==1,"each source retains one video stream");NativeTestSha256 video_hash;std::array<std::uint8_t,131072> video_buffer{};for(std::uint64_t at=0;at<videos[0].bytes;){const auto count=static_cast<std::size_t>(std::min<std::uint64_t>(video_buffer.size(),videos[0].bytes-at));check(index->read_range(videos[0].stream_id,at,std::span(video_buffer).first(count),f),"same-owned video ES observation");video_hash.add(video_buffer.data(),count);at+=count;}const auto video_digest=video_hash.finish();std::printf("{\"key\":");quote(entry.logical_utf8);std::printf(",\"video_streams\":1,\"video_id\":%u,\"video_bytes\":%llu,\"video_pes\":%zu,\"video_es_sha256\":\"%s\",\"audio_streams\":%zu",unsigned(videos[0].stream_id),(unsigned long long)videos[0].bytes,videos[0].spans.size(),video_digest.c_str(),audios.size());
        if(audios.empty()){++video_only;std::puts(",\"audio\":null}");continue;}
        check(audios.size()==1&&audios[0].stream_id==0xc0,"actual corpus single C0 audio");++audio_count;const auto& audio=audios[0];std::string spans="[";std::uint64_t absent_pts=0,absent_dts=0;bool comma=false;for(const auto& span:audio.spans){if(comma)spans+=',';comma=true;spans+="["+std::to_string(span.packet_offset)+","+std::to_string(span.payload_offset)+","+std::to_string(span.packet_end)+","+std::to_string(span.es_begin)+","+std::to_string(span.es_end)+","+(span.pts33?std::to_string(*span.pts33):"null")+","+(span.dts33?std::to_string(*span.dts33):"null")+"]";if(!span.pts33)++absent_pts;if(!span.dts33)++absent_dts;}spans+=']';NativeTestSha256 span_hash;span_hash.add(spans.data(),spans.size());const auto span_digest=span_hash.finish();std::printf(",\"audio_span_sha256\":\"%s\",\"audio_pts_absent\":%llu,\"audio_dts_absent\":%llu",span_digest.c_str(),(unsigned long long)absent_pts,(unsigned long long)absent_dts);check(audio.bytes<=SIZE_MAX,"host owned ES vector extent");std::vector<std::uint8_t> es(static_cast<std::size_t>(audio.bytes));check(index->read_range(audio.stream_id,0,es,f),"same-open complete audio ES");auto reader=index->reader(audio.stream_id,f);check(reader&&reader->validate_next(es,f)&&reader->finished(),"entire exact advancing audio validation");MovieAdxHeaderFailure hf;auto header=parse_movie_adx_header(es,hf);check(bool(header),"actual owned source header");
        auto single=decode(es,false),chunked=decode(es,true);const auto n=header->declared_samples;const auto raw=((n+31)/32)*32;check(single.count==n&&chunked.count==n&&single.reported_raw==raw&&chunked.reported_raw==raw&&single.final.published_frames==n&&single.final.raw_decoded_frames==raw&&chunked.final.raw_decoded_frames==raw,"declared count and full group histories");check(single.pcm==chunked.pcm&&single.final.histories==chunked.final.histories&&single.final.marker==chunked.final.marker,"one-feed versus arbitrary deterministic fragmentation exact");check(single.final.header->raw_header==header->raw_header&&chunked.final.header->raw_header==header->raw_header,"same exact header");check(single.final.marker.size()==18&&single.final.marker[0]==0x80&&single.final.marker[1]==1&&single.final.marker[2]==0&&single.final.marker[3]==14,"actual corpus exact18 marker");
        std::printf(",\"audio_id\":%u,\"audio_pes\":%zu,\"audio_es_bytes\":%llu,\"audio_es_sha256\":\"%s\",\"header_hex\":\"",unsigned(audio.stream_id),audio.spans.size(),(unsigned long long)audio.bytes,digest(es).c_str());hex(header->raw_header);std::printf("\",\"data_start\":%llu,\"encoding\":%u,\"block_bytes\":%u,\"sample_bits\":%u,\"source_planes\":%u,\"sample_rate\":%llu,\"declared_samples\":%llu,\"cutoff\":%u,\"version\":%u,\"flags\":%u,\"initial_histories\":[[%d,%d],[%d,%d]],\"raw_decoded_frames\":%llu,\"groups\":%llu,\"partial_trim\":%llu,\"pcm_interleaved_s16le_sha256\":\"%s\",\"final_histories\":[[%d,%d],[%d,%d]],\"marker_hex\":\"",(unsigned long long)header->data_start,unsigned(header->encoding),unsigned(header->block_bytes),unsigned(header->sample_bits),unsigned(header->source_planes),(unsigned long long)header->sample_rate,(unsigned long long)n,unsigned(header->cutoff),unsigned(header->version),unsigned(header->flags),int(header->histories[0].first),int(header->histories[0].second),int(header->histories[1].first),int(header->histories[1].second),(unsigned long long)raw,(unsigned long long)(raw/32),(unsigned long long)(raw-n),single.pcm.c_str(),int(single.final.histories[0].first),int(single.final.histories[0].second),int(single.final.histories[1].first),int(single.final.histories[1].second));hex(single.final.marker);std::puts("\"}");
    }
    check(audio_count==29&&video_only==9,"actual29audio/9video-only coverage");std::puts("PASS native ADX real29 audio streams and9 video-only sources; no AVPacket or playback admission");check(!std::fflush(stdout)&&!std::ferror(stdout),"complete corpus output");return 0;
}catch(const std::exception& e){std::fprintf(stderr,"FAIL ADX audio assets %s\n",e.what());return 1;}}
